.project-list { display: grid; gap: 10px; margin-top: 28px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; border: 1px solid #dfe5ec; border-radius: 8px; background: white; }
.project-name { overflow-wrap: anywhere; font-weight: 600; }
.back-button { margin-top: 30px; background: #526174; }
.back-button + h1 { margin-top: 24px; }
